INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5907321, 861287, 40718, '<td valign="top">Aww, first picture to come up.  I miss The Egg!</td>', 'Aww, first picture to come up.  I miss The Egg!', '2010-03-17 00:04:24.000000', NULL, 1),
(5907336, 861209, 66515, '<td valign="top">really missing the architecture here.</td>', 'really missing the architecture here.', '2010-03-17 00:08:41.000000', NULL, 1),
(5907346, 861267, 66515, '<td valign="top">Like the use of IR to give it an even more bizarre feel.</td>', 'Like the use of IR to give it an even more bizarre feel.', '2010-03-17 00:10:03.000000', NULL, 1),
(5907351, 861277, 66515, '<td valign="top">different and unique but um...not a piece of architecture. A building or a bridge would fit. Sculpture does not. If this is part of a larger structure I am not able to see it.</td>', 'different and unique but um...not a piece of architecture. A building or a bridge would fit. Sculpture does not. If this is part of a larger structure I am not able to see it.', '2010-03-17 00:10:55.000000', NULL, 1),
(5907352, 861236, 66515, '<td valign="top">hmm...different but that''s not a building or a bridge etc. and hence is not architecture. If this is part of a larger structure I am not able to see it.</td>', 'hmm...different but that''s not a building or a bridge etc. and hence is not architecture. If this is part of a larger structure I am not able to see it.', '2010-03-17 00:10:57.000000', NULL, 1),
(5907354, 861287, 12253, '<td valign="top">I thought about a trip to Albany for this one (only 20 minutes away for me)...but I''ve just been too busy.  Definitely comes to mind when you think Bizarre!  I like the little flare you got at the top...it would be cool if that were even bigger.<br/> <br/>No vote, comment only.</td>', 'I thought about a trip to Albany for this one (only 20 minutes away for me)...but I''ve just been too busy.  Definitely comes to mind when you think Bizarre!  I like the little flare you got at the top...it would be cool if that were even bigger. No vote, comment only.', '2010-03-17 00:10:58.000000', NULL, 1),
(5907357, 860979, 7743, '<td valign="top">St. John''s? Steep hill?<br/> <br/>I like the tilt you applied.</td>', 'St. John''s? Steep hill? I like the tilt you applied.', '2010-03-17 00:12:16.000000', NULL, 1),
(5907376, 861339, 115307, '<td valign="top">This is a difficult photo too score.<br/>Yes, it is certainly bizarre<br/>And yes, it is the clutteredness of it that makes it bizarre.<br/>BUT it is SO cluttered that it makes my eyes hurt.</td>', 'This is a difficult photo too score.Yes, it is certainly bizarreAnd yes, it is the clutteredness of it that makes it bizarre.BUT it is SO cluttered that it makes my eyes hurt.', '2010-03-17 00:17:29.000000', NULL, 1),
(5907390, 861180, 115307, '<td valign="top">Certainly a very bizarre building! But I can''t help but think that you could have done something more interesting with the composition. Especially when you have such a great subject to work with!</td>', 'Certainly a very bizarre building! But I can''t help but think that you could have done something more interesting with the composition. Especially when you have such a great subject to work with!', '2010-03-17 00:20:48.000000', NULL, 1),
(5907401, 860425, 115307, '<td valign="top">Meh. Would this building really be that bizarre if you hadn''t inverted the colors for everything?</td>', 'Meh. Would this building really be that bizarre if you hadn''t inverted the colors for everything?', '2010-03-17 00:23:26.000000', NULL, 1),
(5907404, 861089, 83313, '<td valign="top">Not totally bizarre, but certainly unusual architecture for a temple. Nicely done. Excellent color tones for a night time shot.</td>', 'Not totally bizarre, but certainly unusual architecture for a temple. Nicely done. Excellent color tones for a night time shot.', '2010-03-17 00:23:35.000000', NULL, 1),
(5907405, 861284, 44877, '<td valign="top">Hey - I almost went down to Tempe to shoot city hall, but then decided on something else. I''ll be curious to see who you are. Good luck - great image!</td>', 'Hey - I almost went down to Tempe to shoot city hall, but then decided on something else. I''ll be curious to see who you are. Good luck - great image!', '2010-03-17 00:23:43.000000', NULL, 1),
(5907407, 861126, 114285, '<td valign="top">Wow, that is too weird. Looks Real.</td>', 'Wow, that is too weird. Looks Real.', '2010-03-17 00:23:55.000000', NULL, 1),
(5907416, 861209, 115307, '<td valign="top">Nice try :-P<br/>But this is a shoehorn if I have ever seen one, and not a building</td>', 'Nice try :-PBut this is a shoehorn if I have ever seen one, and not a building', '2010-03-17 00:25:44.000000', NULL, 1),
(5907418, 861277, 83313, '<td valign="top">It''s certainly bizarre. There are some dinosaur sculptures at the Ripley''s museum near me that are done in a very similar fashion. Not sure if this is really architecture in my narrow-minded opinion. Cropped a touch on the close side for my preferences.</td>', 'It''s certainly bizarre. There are some dinosaur sculptures at the Ripley''s museum near me that are done in a very similar fashion. Not sure if this is really architecture in my narrow-minded opinion. Cropped a touch on the close side for my preferences.', '2010-03-17 00:26:21.000000', NULL, 1),
(5907420, 861097, 83313, '<td valign="top">Great tones. patterns and light. B/W was the perfect choice for this.</td>', 'Great tones. patterns and light. B/W was the perfect choice for this.', '2010-03-17 00:27:00.000000', NULL, 1),
(5907422, 860979, 66515, '<td valign="top">lol...had me fooled for a moment. Great idea. :)</td>', 'lol...had me fooled for a moment. Great idea. :)', '2010-03-17 00:27:33.000000', NULL, 1),
(5907430, 861343, 74911, '<td valign="top">Good one... i''m being reminded of this image --&gt; <a href="//www.dpchallenge.com/image.php?IMAGE_ID=801551" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1054/120/Copyrighted_Image_Reuse_Prohibited_801551.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1054/120/Copyrighted_Image_Reuse_Prohibited_801551.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1054/120/Copyrighted_Image_Reuse_Prohibited_801551.jpg"/></a></td>', 'Good one... i''m being reminded of this image --> ', '2010-03-17 00:28:54.000000', NULL, 1),
(5907439, 861248, 83313, '<td valign="top">Congratulations, you are the first recipient of one of my infamous compression comments for this challenge!<br/> <br/>It''s a cool looking abstract shot, with one major problem. Tons of blocky compression artifacts are showing. Your 15k file size confirms that you uses a lot of JPEG compression when you saved this.  Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.</td>', 'Congratulations, you are the first recipient of one of my infamous compression comments for this challenge! It''s a cool looking abstract shot, with one major problem. Tons of blocky compression artifacts are showing. Your 15k file size confirms that you uses a lot of JPEG compression when you saved this.  Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.', '2010-03-17 00:30:14.000000', NULL, 1),
(5907440, 860453, 74911, '<td valign="top">Amazing B&amp;W shot. Great way to meet the challenge. I hope this shows up on the first page. Good luck.<br/> <br/>Raj</td>', 'Amazing B&W shot. Great way to meet the challenge. I hope this shows up on the first page. Good luck. Raj', '2010-03-17 00:30:21.000000', NULL, 1),
(5907447, 861238, 74911, '<td valign="top">Nice way to meet the challenge.<br/> <br/>Raj</td>', 'Nice way to meet the challenge. Raj', '2010-03-17 00:32:04.000000', NULL, 1),
(5907448, 860641, 83313, '<td valign="top">Either some good OOTB thinking or a shoehorn. It''s a fine line sometimes.</td>', 'Either some good OOTB thinking or a shoehorn. It''s a fine line sometimes.', '2010-03-17 00:32:15.000000', NULL, 1),
(5907449, 860235, 74911, '<td valign="top">Good use of negative space. The white spot due to lens flare bothers a bit.<br/> <br/>Raj</td>', 'Good use of negative space. The white spot due to lens flare bothers a bit. Raj', '2010-03-17 00:32:41.000000', NULL, 1),
(5907450, 861097, 74911, '<td valign="top">Great shot. While including the people shows the scale of the architecture, I would still have preferred a crop that would exclude the people there.</td>', 'Great shot. While including the people shows the scale of the architecture, I would still have preferred a crop that would exclude the people there.', '2010-03-17 00:32:45.000000', NULL, 1),
(5907456, 860673, 83313, '<td valign="top">Not bizarre, but somewhat unusual, especially with the angle you shot at. I am being fairly loose with the challenge description, since not everyone has something totally insane near them. We can all find something a little unusual, however.</td>', 'Not bizarre, but somewhat unusual, especially with the angle you shot at. I am being fairly loose with the challenge description, since not everyone has something totally insane near them. We can all find something a little unusual, however.', '2010-03-17 00:33:55.000000', NULL, 1),
(5907460, 861209, 74911, '<td valign="top">While this is a good shot, I am afraid if you are going to be punished for not meeting the challenge.<br/> <br/>Raj</td>', 'While this is a good shot, I am afraid if you are going to be punished for not meeting the challenge. Raj', '2010-03-17 00:34:50.000000', NULL, 1),
(5907471, 861151, 83313, '<td valign="top">Mildly unusual, though not bizarre. Not everyone has an upside down house near them. The big issue for me with this image is that it looks somewhat dull and flat. I copied and pasted this into PaintShop Pro and found that a quick levels adjustment brightened it up a lot and brought out lots of nice detail.</td>', 'Mildly unusual, though not bizarre. Not everyone has an upside down house near them. The big issue for me with this image is that it looks somewhat dull and flat. I copied and pasted this into PaintShop Pro and found that a quick levels adjustment brightened it up a lot and brought out lots of nice detail.', '2010-03-17 00:38:04.000000', NULL, 1),
(5907478, 860466, 83313, '<td valign="top">The tip of the building being cut off doesn''t work for me, making the composition seem awkward. Some very nice clarity and good colors, though.</td>', 'The tip of the building being cut off doesn''t work for me, making the composition seem awkward. Some very nice clarity and good colors, though.', '2010-03-17 00:40:35.000000', NULL, 1),
(5907485, 861180, 25355, '<td valign="top">Hey, that''s that new hotel in Zaandam! I think it''s a pity you couldn''t have included the bottom floors.</td>', 'Hey, that''s that new hotel in Zaandam! I think it''s a pity you couldn''t have included the bottom floors.', '2010-03-17 00:42:26.000000', NULL, 1),
(5907564, 861126, 30861, '<td valign="top">Gawd I love this building. I''ve always loved this building. You may know I spent my working life as an Architectural Photographer, or you may not, but anyway I love stuff like this.<br/> <br/>It''s a decent POV, the light''s just mediocre of course, but I''m sure you''re aware of that and had no control over it. FINE subject, about as bizarre as architecture of the corporate variety can get :-)</td>', 'Gawd I love this building. I''ve always loved this building. You may know I spent my working life as an Architectural Photographer, or you may not, but anyway I love stuff like this. It''s a decent POV, the light''s just mediocre of course, but I''m sure you''re aware of that and had no control over it. FINE subject, about as bizarre as architecture of the corporate variety can get :-)', '2010-03-17 01:08:44.000000', NULL, 1),
(5907567, 861182, 30861, '<td valign="top">Very nicely done. I''ve seen this before, and marveled at it before :-)</td>', 'Very nicely done. I''ve seen this before, and marveled at it before :-)', '2010-03-17 01:09:47.000000', NULL, 1),
(5907597, 861126, 10084, '<td valign="top">Winner. "10"</td>', 'Winner. "10"', '2010-03-17 01:21:29.000000', NULL, 1),
(5907677, 860393, 106910, '<td valign="top">Awesome subject - but I feel like the composition could have been arranged better so that the house is less integral to the image. Still - I like it - 6.</td>', 'Awesome subject - but I feel like the composition could have been arranged better so that the house is less integral to the image. Still - I like it - 6.', '2010-03-17 02:34:39.000000', NULL, 1),
(5907731, 861097, 25355, '<td valign="top">I was wondering if anyone would enter the SOH; I think it''s probably so familiar to people around the world that it''s possibly not so bizarre anymore. Anyway, you''ve got a good shot of it and you must have had quite a quick shutter speed because there''s very little blurring among the people.</td>', 'I was wondering if anyone would enter the SOH; I think it''s probably so familiar to people around the world that it''s possibly not so bizarre anymore. Anyway, you''ve got a good shot of it and you must have had quite a quick shutter speed because there''s very little blurring among the people.', '2010-03-17 04:41:20.000000', NULL, 1),
(5907732, 861287, 25355, '<td valign="top">I like the colours, but your HDR processing has left too much undesirable fringing around in the sky.</td>', 'I like the colours, but your HDR processing has left too much undesirable fringing around in the sky.', '2010-03-17 04:45:01.000000', NULL, 1),
(5907735, 861236, 25355, '<td valign="top">More of a sculpture than architecture.</td>', 'More of a sculpture than architecture.', '2010-03-17 04:47:42.000000', NULL, 1),
(5907739, 861126, 25355, '<td valign="top">Hmm, something missing ... a stick of French bread, a bit of gingham checked cloth, maybe a pickle jar sticking out... ;-Þ</td>', 'Hmm, something missing ... a stick of French bread, a bit of gingham checked cloth, maybe a pickle jar sticking out... ;-Þ', '2010-03-17 04:57:50.000000', NULL, 1),
(5907772, 860699, 18655, '<td valign="top">Great colors and perspective - 8</td>', 'Great colors and perspective - 8', '2010-03-17 06:10:37.000000', NULL, 1),
(5907774, 860920, 18655, '<td valign="top">Nicely done. Good balance</td>', 'Nicely done. Good balance', '2010-03-17 06:12:16.000000', NULL, 1),
(5907775, 860642, 18655, '<td valign="top">Great B/W shot. Interesting subject, funny and sharp - 9</td>', 'Great B/W shot. Interesting subject, funny and sharp - 9', '2010-03-17 06:14:08.000000', NULL, 1),
(5907776, 861102, 18655, '<td valign="top">Been there myself. Nice interpretation and well executed - 8</td>', 'Been there myself. Nice interpretation and well executed - 8', '2010-03-17 06:15:09.000000', NULL, 1),
(5907788, 861244, 25355, '<td valign="top">I guess that''s what you''ve got to expect if you live in an earthquake zone. ;-)</td>', 'I guess that''s what you''ve got to expect if you live in an earthquake zone. ;-)', '2010-03-17 06:34:53.000000', NULL, 1),
(5907869, 861342, 113278, '<td valign="top">This looks oddly like a house in Lynchburg, VA. Is it?? Not really all that bizarre but I do like the errieness of it so 7.</td>', 'This looks oddly like a house in Lynchburg, VA. Is it?? Not really all that bizarre but I do like the errieness of it so 7.', '2010-03-17 07:44:45.000000', NULL, 1),
