(5907916, 860247, 43774, '<td valign="top">Ha, how cute!!</td>', 'Ha, how cute!!', '2010-03-17 08:32:22.000000', NULL, 1),
(5907919, 861325, 43774, '<td valign="top">Very cool. This must be either the Museum of the American Indian in Washington, DC or the Museum of Civilization in Hull, Quebec.</td>', 'Very cool. This must be either the Museum of the American Indian in Washington, DC or the Museum of Civilization in Hull, Quebec.', '2010-03-17 08:33:53.000000', NULL, 1),
(5907923, 861284, 43774, '<td valign="top">Bizarre yes but way over processed.</td>', 'Bizarre yes but way over processed.', '2010-03-17 08:36:17.000000', NULL, 1),
