(5907927, 860453, 43774, '<td valign="top">Best in the challenge, this is really neat.</td>', 'Best in the challenge, this is really neat.', '2010-03-17 08:39:56.000000', NULL, 1),
(5907928, 861097, 43774, '<td valign="top">Is this the Sydney Opea House? Fantastic composition. If it is, my guess is that this is HotPasta''s photo......signature black border. In my top 3.</td>', 'Is this the Sydney Opea House? Fantastic composition. If it is, my guess is that this is HotPasta''s photo......signature black border. In my top 3.', '2010-03-17 08:41:33.000000', NULL, 1),
(5907967, 861182, 109478, '<td valign="top">Well exposured and nice color, cute house.</td>', 'Well exposured and nice color, cute house.', '2010-03-17 09:14:45.000000', NULL, 1),
(5907974, 861187, 109478, '<td valign="top">I wish that I can photo this architecture, too.</td>', 'I wish that I can photo this architecture, too.', '2010-03-17 09:17:33.000000', NULL, 1),
