(5908003, 861182, 72929, '<td valign="top">this one is weird. Nice texture/sharpening work.</td>', 'this one is weird. Nice texture/sharpening work.', '2010-03-17 09:40:54.000000', NULL, 1),
(5908007, 861126, 72929, '<td valign="top">Hahahaa.. it''s funny that this is serious for real. Is it an eyesore or an attraction? Only the residents can decide.</td>', 'Hahahaa.. it''s funny that this is serious for real. Is it an eyesore or an attraction? Only the residents can decide.', '2010-03-17 09:43:51.000000', NULL, 1),
