(5908012, 861267, 72929, '<td valign="top">This perspective is much better than the other geisel library shot. And the fact you shot it in IR makes it that much more interesting.</td>', 'This perspective is much better than the other geisel library shot. And the fact you shot it in IR makes it that much more interesting.', '2010-03-17 09:45:18.000000', NULL, 1),
(5908098, 861164, 113591, '<td valign="top">Wow, totally outlandish. Can''t stop looking.</td>', 'Wow, totally outlandish. Can''t stop looking.', '2010-03-17 11:06:45.000000', NULL, 1),
(5908100, 860530, 113591, '<td valign="top">This makes my eyes squint, so it must be buzarre.</td>', 'This makes my eyes squint, so it must be buzarre.', '2010-03-17 11:09:22.000000', NULL, 1),
(5908111, 861343, 113591, '<td valign="top">After staring at the picture for a lon while, I suddenly realised that there were half-moons of dust? right round the building. Is it an optical illusion?</td>', 'After staring at the picture for a lon while, I suddenly realised that there were half-moons of dust? right round the building. Is it an optical illusion?', '2010-03-17 11:13:38.000000', NULL, 1),
