(5908131, 861218, 113591, '<td valign="top">Nice co;ours, certainly unusual</td>', 'Nice co;ours, certainly unusual', '2010-03-17 11:26:45.000000', NULL, 1),
(5908134, 860917, 115307, '<td valign="top">Its a nice building, but way too over exposed for me.</td>', 'Its a nice building, but way too over exposed for me.', '2010-03-17 11:30:35.000000', NULL, 1),
(5908137, 860944, 113591, '<td valign="top">The pastel blues in front does it for me.</td>', 'The pastel blues in front does it for me.', '2010-03-17 11:32:54.000000', NULL, 1),
(5908138, 861267, 115307, '<td valign="top">I said I was going to eat my hat if this library didn''t end up in the challenge somewhere. Thank you for saving me that discomfort! :-P<br/>And a fine image at that.</td>', 'I said I was going to eat my hat if this library didn''t end up in the challenge somewhere. Thank you for saving me that discomfort! :-PAnd a fine image at that.', '2010-03-17 11:33:17.000000', NULL, 1),
