(5908158, 860979, 113591, '<td valign="top">More impact if your false horizon was horizontal?</td>', 'More impact if your false horizon was horizontal?', '2010-03-17 11:47:48.000000', NULL, 1),
(5908190, 861182, 99263, '<td valign="top">Absolutely stunning image. Just perfect. Beautiful composition, striking colors, some lovely textures and incredibly fine detail combine to make this really stand out. I daresay that this will finish in the top 3 and I even suspect it might take the coveted blue ribbon.  10</td>', 'Absolutely stunning image. Just perfect. Beautiful composition, striking colors, some lovely textures and incredibly fine detail combine to make this really stand out. I daresay that this will finish in the top 3 and I even suspect it might take the coveted blue ribbon.  10', '2010-03-17 11:59:29.000000', NULL, 1),
