(5909050, 861180, 113411, '<td valign="top">A great capture for this challenge! Really well done.</td>', 'A great capture for this challenge! Really well done.', '2010-03-17 21:30:41.000000', NULL, 1),
(5909051, 860287, 43088, '<td valign="top">Seems blury</td>', 'Seems blury', '2010-03-17 21:30:47.000000', NULL, 1),
