(5909120, 860473, 113419, '<td valign="top">lighting is kinda harsh</td>', 'lighting is kinda harsh', '2010-03-17 23:01:52.000000', NULL, 1),
(5909121, 861180, 113419, '<td valign="top">man that is amazing</td>', 'man that is amazing', '2010-03-17 23:02:22.000000', NULL, 1),
(5909123, 861325, 113419, '<td valign="top">what an amazing image</td>', 'what an amazing image', '2010-03-17 23:03:00.000000', NULL, 1),
(5909125, 861059, 113419, '<td valign="top">good picture</td>', 'good picture', '2010-03-17 23:03:36.000000', NULL, 1),
(5909126, 860979, 44025, '<td valign="top">I appreciate it, but I can''t give it a very high score. 5. I think it''s th elighting. Although it''s a reaity shot, sunset or sunrise shooting would have made it so much better. Great concept</td>', 'I appreciate it, but I can''t give it a very high score. 5. I think it''s th elighting. Although it''s a reaity shot, sunset or sunrise shooting would have made it so much better. Great concept', '2010-03-17 23:03:48.000000', NULL, 1),
(5909129, 861253, 113419, '<td valign="top">cool</td>', 'cool', '2010-03-17 23:04:35.000000', NULL, 1),
(5909131, 860642, 113419, '<td valign="top">neat!  I like it!</td>', 'neat!  I like it!', '2010-03-17 23:06:04.000000', NULL, 1),
(5909225, 860673, 89223, '<td valign="top">love the sharp lines, the sky really sets the mood rite fir this photo very nice work</td>', 'love the sharp lines, the sky really sets the mood rite fir this photo very nice work', '2010-03-18 00:26:25.000000', NULL, 1),
(5909227, 860720, 89223, '<td valign="top">thursty? lol great find!</td>', 'thursty? lol great find!', '2010-03-18 00:27:30.000000', NULL, 1),
(5909275, 860917, 46918, '<td valign="top">Way too white...The color is washed out</td>', 'Way too white...The color is washed out', '2010-03-18 02:57:01.000000', NULL, 1),
(5909277, 860487, 46918, '<td valign="top">Great shot...It looks like it was taken 100 years ago...Good job</td>', 'Great shot...It looks like it was taken 100 years ago...Good job', '2010-03-18 02:58:01.000000', NULL, 1),
(5909290, 860699, 113591, '<td valign="top">What a fun picture! 10 from me!</td>', 'What a fun picture! 10 from me!', '2010-03-18 04:00:32.000000', NULL, 1),
(5909297, 861049, 113591, '<td valign="top">The light reflected from the crests make the structure more real. I also like the shadows of the trees, and the branchaes. Increases the difference between normal and bizzarre</td>', 'The light reflected from the crests make the structure more real. I also like the shadows of the trees, and the branchaes. Increases the difference between normal and bizzarre', '2010-03-18 04:26:02.000000', NULL, 1),
(5909298, 861325, 113591, '<td valign="top">The light and shadows make this building seem alive to me, in the "the monster is alive and coming" sense. One of my favourites.</td>', 'The light and shadows make this building seem alive to me, in the "the monster is alive and coming" sense. One of my favourites.', '2010-03-18 04:28:01.000000', NULL, 1),
(5909299, 861267, 113591, '<td valign="top">How on earth.....? Well done! Bumping up to 9</td>', 'How on earth.....? Well done! Bumping up to 9', '2010-03-18 04:29:35.000000', NULL, 1),
(5909300, 861182, 113591, '<td valign="top">You captured the marsipan roof and candy walls feeling perfectly. Bumping up</td>', 'You captured the marsipan roof and candy walls feeling perfectly. Bumping up', '2010-03-18 04:31:31.000000', NULL, 1),
(5909301, 861097, 113591, '<td valign="top">The slant of the picture caught my eye, and after thinking about it, I don''t have a clue if I like it or not. I like the lighting on the domes, and the B&amp;W.</td>', 'The slant of the picture caught my eye, and after thinking about it, I don''t have a clue if I like it or not. I like the lighting on the domes, and the B&W.', '2010-03-18 04:35:02.000000', NULL, 1),
(5909307, 861180, 113591, '<td valign="top">It''s nice to see only this building, it enforces the idea of a lot of houses in one for me.</td>', 'It''s nice to see only this building, it enforces the idea of a lot of houses in one for me.', '2010-03-18 04:52:50.000000', NULL, 1),
(5909308, 860322, 113591, '<td valign="top">Really strange building, and taken to show it in it''s strangeness. Bumping up</td>', 'Really strange building, and taken to show it in it''s strangeness. Bumping up', '2010-03-18 04:55:00.000000', NULL, 1),
(5909309, 860247, 113591, '<td valign="top">And such a friendly shoe it is.</td>', 'And such a friendly shoe it is.', '2010-03-18 04:56:06.000000', NULL, 1),
(5909312, 861244, 113591, '<td valign="top">Weird man, weird. Only became a normal photo after I had my second pipe. Couldn''t you have sawn off the traffic light poles? The authorities MUST know this building would be photographed very often. Can''t they move the poles?</td>', 'Weird man, weird. Only became a normal photo after I had my second pipe. Couldn''t you have sawn off the traffic light poles? The authorities MUST know this building would be photographed very often. Can''t they move the poles?', '2010-03-18 05:03:47.000000', NULL, 1),
(5909313, 860516, 113591, '<td valign="top">This photo calmed me down. I like that, so bumping up</td>', 'This photo calmed me down. I like that, so bumping up', '2010-03-18 05:04:41.000000', NULL, 1),
(5909314, 860482, 113591, '<td valign="top">I was drawn into the green/yellow centre, wanted to know more. Bumping up</td>', 'I was drawn into the green/yellow centre, wanted to know more. Bumping up', '2010-03-18 05:06:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5909316, 861282, 113591, '<td valign="top">The light is still a bit harsh, but one cannot always sit around for ever, can one?</td>', 'The light is still a bit harsh, but one cannot always sit around for ever, can one?', '2010-03-18 05:07:48.000000', NULL, 1),
(5909318, 861348, 113591, '<td valign="top">If the blackend area was boring, it''s fine, but if not, I would have liked to see more twisting and decay there.</td>', 'If the blackend area was boring, it''s fine, but if not, I would have liked to see more twisting and decay there.', '2010-03-18 05:09:35.000000', NULL, 1),
(5909498, 860641, 109227, '<td valign="top">Needs better focus.</td>', 'Needs better focus.', '2010-03-18 10:42:46.000000', NULL, 1),
(5909502, 860466, 109227, '<td valign="top">Nice capture with the bird.</td>', 'Nice capture with the bird.', '2010-03-18 10:51:04.000000', NULL, 1),
(5909508, 861272, 109227, '<td valign="top">A little too soft.</td>', 'A little too soft.', '2010-03-18 10:57:37.000000', NULL, 1),
(5909509, 860979, 86447, '<td valign="top">VERY clever!</td>', 'VERY clever!', '2010-03-18 10:58:09.000000', NULL, 1),
(5909553, 861187, 6667, '<td valign="top">Erik!?</td>', 'Erik!?', '2010-03-18 11:57:11.000000', NULL, 1),
(5909575, 861339, 60495, '<td valign="top">You found some very Bizarre architecture alright, it is very interesting but to me it''s just way too busy and lacks any clear focal point.  I think it may have helped to get a closer shot but then people would not have seen it as architecture. I am giving it a 6 because it really fits the challenge well but lacks some in overall appeal.</td>', 'You found some very Bizarre architecture alright, it is very interesting but to me it''s just way too busy and lacks any clear focal point.  I think it may have helped to get a closer shot but then people would not have seen it as architecture. I am giving it a 6 because it really fits the challenge well but lacks some in overall appeal.', '2010-03-18 12:26:22.000000', NULL, 1),
(5909584, 861287, 60495, '<td valign="top">Good choice of structures but the shot suffers from being taken at the wrong time of day taken which makes the lighting very flat. Taken earlier or later in the day the shadows and color would have been so much better and made the photo pop. I am also not a big fan of the over use of processing to create texture to the point where it adds halos around the trees and buildings and appears to have added noise to the sky. I give this one a 6 but with better lighting and processing it likely would have been an 8 or 9.</td>', 'Good choice of structures but the shot suffers from being taken at the wrong time of day taken which makes the lighting very flat. Taken earlier or later in the day the shadows and color would have been so much better and made the photo pop. I am also not a big fan of the over use of processing to create texture to the point where it adds halos around the trees and buildings and appears to have added noise to the sky. I give this one a 6 but with better lighting and processing it likely would have been an 8 or 9.', '2010-03-18 12:35:43.000000', NULL, 1),
(5909586, 861325, 60495, '<td valign="top">Great choice of structures and time of day to get the shot. I love the shadows and lighting from the upper level windows. Nicely done! 10</td>', 'Great choice of structures and time of day to get the shot. I love the shadows and lighting from the upper level windows. Nicely done! 10', '2010-03-18 12:38:03.000000', NULL, 1),
(5909587, 861284, 49109, '<td valign="top">overprocessed for my taste</td>', 'overprocessed for my taste', '2010-03-18 12:39:14.000000', NULL, 1),
(5909588, 860322, 60495, '<td valign="top">Awesome building, what a fun shot. 10</td>', 'Awesome building, what a fun shot. 10', '2010-03-18 12:39:37.000000', NULL, 1),
(5909589, 861267, 49109, '<td valign="top">is this really IR or a PP trick? Like it, especially the framing through  foreground trees.</td>', 'is this really IR or a PP trick? Like it, especially the framing through  foreground trees.', '2010-03-18 12:40:36.000000', NULL, 1),
(5909591, 861267, 60495, '<td valign="top">I love the composition and balance of this shot, one of my favorites for the challenge.</td>', 'I love the composition and balance of this shot, one of my favorites for the challenge.', '2010-03-18 12:41:55.000000', NULL, 1),
(5909594, 860979, 60495, '<td valign="top">I do home inspections for a living and I have to tell you I have some concerns here!  Fun shot, like the way you leveled the street to create an interesting shot. the car being there really adds to the effect.</td>', 'I do home inspections for a living and I have to tell you I have some concerns here!  Fun shot, like the way you leveled the street to create an interesting shot. the car being there really adds to the effect.', '2010-03-18 12:45:37.000000', NULL, 1),
(5909597, 860720, 83313, '<td valign="top">Grog like beer, but Grog''s hands too big. Cannot open can. Must get female to open can for Grog.</td>', 'Grog like beer, but Grog''s hands too big. Cannot open can. Must get female to open can for Grog.', '2010-03-18 12:48:14.000000', NULL, 1),
(5909598, 861284, 60495, '<td valign="top">Nice building but the processing is way over the top for my taste. 5</td>', 'Nice building but the processing is way over the top for my taste. 5', '2010-03-18 12:48:34.000000', NULL, 1),
(5909599, 861126, 60495, '<td valign="top">That building always cracked me up, even when you see it in person it really does look like a big basket. I lived in Ohio briefly, not too surprised to see the gray sky! Good luck in the challenge.</td>', 'That building always cracked me up, even when you see it in person it really does look like a big basket. I lived in Ohio briefly, not too surprised to see the gray sky! Good luck in the challenge.', '2010-03-18 12:50:46.000000', NULL, 1),
(5909600, 860393, 60495, '<td valign="top">LOL, how do you explain that to your insurance?</td>', 'LOL, how do you explain that to your insurance?', '2010-03-18 12:51:39.000000', NULL, 1),
(5909601, 861244, 43774, '<td valign="top">This is so cool!!!</td>', 'This is so cool!!!', '2010-03-18 12:52:45.000000', NULL, 1),
(5909602, 861126, 43774, '<td valign="top">I''ve seen pictures of this before, such a cool looking building. Too bad you didn''t have a more interesting sky for the photo, but c''est la vie.</td>', 'I''ve seen pictures of this before, such a cool looking building. Too bad you didn''t have a more interesting sky for the photo, but c''est la vie.', '2010-03-18 12:53:21.000000', NULL, 1),
(5909603, 861287, 83313, '<td valign="top">I like it, though the tonemapping brought out a lot of noise grain in the sky, and a bit of haloing around the buildings. One thing I can do with PaintShop Pro when I do noise reduction, is to apply the noise reduction to the blue and cyan color ranges only. That maintains detail in the other areas, but smooths out the grainy sky. I would assume Photoshop can probably do a similar color channel application of NR, if that is what you are using.</td>', 'I like it, though the tonemapping brought out a lot of noise grain in the sky, and a bit of haloing around the buildings. One thing I can do with PaintShop Pro when I do noise reduction, is to apply the noise reduction to the blue and cyan color ranges only. That maintains detail in the other areas, but smooths out the grainy sky. I would assume Photoshop can probably do a similar color channel application of NR, if that is what you are using.', '2010-03-18 12:53:26.000000', NULL, 1),
(5909604, 861180, 43774, '<td valign="top">How neat!! Love the blue sky too.</td>', 'How neat!! Love the blue sky too.', '2010-03-18 12:53:40.000000', NULL, 1),
(5909605, 861327, 43774, '<td valign="top">How interesting! What is it used for?</td>', 'How interesting! What is it used for?', '2010-03-18 12:53:58.000000', NULL, 1),
(5909606, 861285, 43774, '<td valign="top">Very cool, good photo of this interesting architecture.</td>', 'Very cool, good photo of this interesting architecture.', '2010-03-18 12:54:15.000000', NULL, 1),
(5909607, 861043, 43774, '<td valign="top">Wow, interesting architecture for sure! Not sure I like the sepia tones but I like the composition.</td>', 'Wow, interesting architecture for sure! Not sure I like the sepia tones but I like the composition.', '2010-03-18 12:54:42.000000', NULL, 1),
(5909608, 860720, 60495, '<td valign="top">I am betting the guy is single!</td>', 'I am betting the guy is single!', '2010-03-18 12:54:43.000000', NULL, 1),
(5909609, 861043, 83313, '<td valign="top">Ive seen some pics of this apartment building before. Very weird. Effective wideangle view of it.</td>', 'Ive seen some pics of this apartment building before. Very weird. Effective wideangle view of it.', '2010-03-18 12:55:00.000000', NULL, 1),
(5909612, 861102, 83313, '<td valign="top">Looks like the time machine malfunctioned.</td>', 'Looks like the time machine malfunctioned.', '2010-03-18 12:55:59.000000', NULL, 1),
(5909616, 861042, 83313, '<td valign="top">Whether or not this is really an unusual building I can''t know, but your effective use a semi-abstract perspective makes it that way.</td>', 'Whether or not this is really an unusual building I can''t know, but your effective use a semi-abstract perspective makes it that way.', '2010-03-18 12:57:37.000000', NULL, 1),
(5909619, 860404, 83313, '<td valign="top">Not really unusual, though I am being fairly open in my interpretation of the topic. The image as a whole is kind of soft looking and the tones are a bit on the flat side. I see some good effort on the composition, however. It tries to lead my eye, though that board at the bottom left is stopping my eye from being taken where it the image is trying to lead it.</td>', 'Not really unusual, though I am being fairly open in my interpretation of the topic. The image as a whole is kind of soft looking and the tones are a bit on the flat side. I see some good effort on the composition, however. It tries to lead my eye, though that board at the bottom left is stopping my eye from being taken where it the image is trying to lead it.', '2010-03-18 13:01:18.000000', NULL, 1),
(5909622, 860473, 83313, '<td valign="top">Looks like you used some on-camera flash here. Ack! If there is any ambient light to use, a tripod and longer exposure will almost always give better results than the onboard flash will. An interesting subject, however.</td>', 'Looks like you used some on-camera flash here. Ack! If there is any ambient light to use, a tripod and longer exposure will almost always give better results than the onboard flash will. An interesting subject, however.', '2010-03-18 13:03:36.000000', NULL, 1),
(5909623, 861209, 83313, '<td valign="top">Sorry, as nice a shot as this is, I can''t stretch my definition of architecture to include a flower.</td>', 'Sorry, as nice a shot as this is, I can''t stretch my definition of architecture to include a flower.', '2010-03-18 13:05:35.000000', NULL, 1),
(5909624, 861182, 83313, '<td valign="top">That''s an interesting building. Some kind of hunting cabin?</td>', 'That''s an interesting building. Some kind of hunting cabin?', '2010-03-18 13:06:22.000000', NULL, 1),
(5909627, 861267, 83313, '<td valign="top">Geisel, as in Dr. Seuss? I guess the infrared look works for this, making the trees into Seussian caricature of themselves. The processing you''ve done on this gives it a bit of an "artists conception" look, which I find appropriate.</td>', 'Geisel, as in Dr. Seuss? I guess the infrared look works for this, making the trees into Seussian caricature of themselves. The processing you''ve done on this gives it a bit of an "artists conception" look, which I find appropriate.', '2010-03-18 13:09:21.000000', NULL, 1),
(5909628, 860425, 83313, '<td valign="top">I''m not a big fan of the negative image look. Once in a while it works, but I''m not caring for it here. Please consider that a personal preference thing and not any real flaw.</td>', 'I''m not a big fan of the negative image look. Once in a while it works, but I''m not caring for it here. Please consider that a personal preference thing and not any real flaw.', '2010-03-18 13:12:19.000000', NULL, 1),
(5909629, 861295, 83313, '<td valign="top">Very strange looking and the treatment is appropriate.</td>', 'Very strange looking and the treatment is appropriate.', '2010-03-18 13:12:53.000000', NULL, 1),
(5909632, 861126, 83313, '<td valign="top">Good to see that someone lived close enough for this to get in the challenge. Interesting subject, but to be honest, I find the shot itself to be kind of plain. Sorry.</td>', 'Good to see that someone lived close enough for this to get in the challenge. Interesting subject, but to be honest, I find the shot itself to be kind of plain. Sorry.', '2010-03-18 13:14:26.000000', NULL, 1),
(5909633, 860979, 83313, '<td valign="top">Judging from the way the curtains are hanging, I''d say it''s the hill that is angled. Gotta give you kudos for creative thinking on this, however. It is very effective until I look at the details. Interesting that the no parking sign is tilted with the hill.</td>', 'Judging from the way the curtains are hanging, I''d say it''s the hill that is angled. Gotta give you kudos for creative thinking on this, however. It is very effective until I look at the details. Interesting that the no parking sign is tilted with the hill.', '2010-03-18 13:17:02.000000', NULL, 1),
(5909634, 861245, 83313, '<td valign="top">Just not finding this grabs my attention much, and I don''t see anything unusual about the structure. Sorry.</td>', 'Just not finding this grabs my attention much, and I don''t see anything unusual about the structure. Sorry.', '2010-03-18 13:18:16.000000', NULL, 1),
(5909639, 860565, 83313, '<td valign="top">Now THIS is cave for Grog! Will make Thag very jealous. How much is mortgage on dream cave? Does cave have working plumbing and cable? BTW, Grog cannot spell <strike>medeval</strike> <strike>meadivul</strike> <strike>medeevil</strike> either.</td>', 'Now THIS is cave for Grog! Will make Thag very jealous. How much is mortgage on dream cave? Does cave have working plumbing and cable? BTW, Grog cannot spell medeval meadivul medeevil either.', '2010-03-18 13:30:45.000000', NULL, 1),
(5909641, 860421, 83313, '<td valign="top">Very cute. House being cut off at the frame edge is a problem.</td>', 'Very cute. House being cut off at the frame edge is a problem.', '2010-03-18 13:31:47.000000', NULL, 1),
(5909647, 860642, 83313, '<td valign="top">There is one of these somewhere out east of Dallas, but it was too far for me to drive to for this challenge. I would be tempted to think this was shot by <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=104518" rel="nofollow" target="_blank">Retiredphil</a>, who lives out that way, but I don''t think the Texas saucer is in as good a shape as this one, and I think it''s also in a field.</td>', 'There is one of these somewhere out east of Dallas, but it was too far for me to drive to for this challenge. I would be tempted to think this was shot by  Retiredphil, who lives out that way, but I don''t think the Texas saucer is in as good a shape as this one, and I think it''s also in a field.', '2010-03-18 13:37:00.000000', NULL, 1),
(5909648, 861188, 83313, '<td valign="top">Harsh overhead midday sun is the only thing that''s a big problem with this.</td>', 'Harsh overhead midday sun is the only thing that''s a big problem with this.', '2010-03-18 13:38:12.000000', NULL, 1),
(5909770, 861253, 83313, '<td valign="top">That''s interesting. Not bad as it stands, though perhaps it could benefit from a modest bump in contrast and saturation, just to give it a little more visual pop.</td>', 'That''s interesting. Not bad as it stands, though perhaps it could benefit from a modest bump in contrast and saturation, just to give it a little more visual pop.', '2010-03-18 16:48:03.000000', NULL, 1),
(5909772, 861187, 83313, '<td valign="top">You clearly staked this place out to get your shot in the perfect lighting conditions.</td>', 'You clearly staked this place out to get your shot in the perfect lighting conditions.', '2010-03-18 16:49:07.000000', NULL, 1),
(5909773, 860979, 57447, '<td valign="top">What a trip.</td>', 'What a trip.', '2010-03-18 16:49:55.000000', NULL, 1),
(5909775, 860878, 57447, '<td valign="top">Great place, nice entry.</td>', 'Great place, nice entry.', '2010-03-18 16:52:52.000000', NULL, 1),
(5909777, 861316, 83313, '<td valign="top">Grog go to water buffalo lodge in Odawa for party, fancy place for Grog. Invited by Fred Flintstone who always keep up with the Jonesrocks. Fred now in debt up to eyeballs. Grog tell Fred about <a href="//www.daveramsey.com/category/show/" rel="nofollow" target="_blank">Dave Ramstone</a>.</td>', 'Grog go to water buffalo lodge in Odawa for party, fancy place for Grog. Invited by Fred Flintstone who always keep up with the Jonesrocks. Fred now in debt up to eyeballs. Grog tell Fred about Dave Ramstone.', '2010-03-18 16:55:14.000000', NULL, 1),
(5909801, 861284, 66515, '<td valign="top">not really a fan of the processing as it looks like noise has been introduced as a result. The building itself however is an excellent choice for this challenge.</td>', 'not really a fan of the processing as it looks like noise has been introduced as a result. The building itself however is an excellent choice for this challenge.', '2010-03-18 17:39:05.000000', NULL, 1),
(5909871, 860979, 108580, '<td valign="top">Clever tilt.</td>', 'Clever tilt.', '2010-03-18 19:00:26.000000', NULL, 1),
(5909876, 860641, 108580, '<td valign="top">Clever shot, hope you don''t get hammered. Focus off and heavily cropped but I wouldn''t get too close either...</td>', 'Clever shot, hope you don''t get hammered. Focus off and heavily cropped but I wouldn''t get too close either...', '2010-03-18 19:02:52.000000', NULL, 1),
(5909965, 860393, 83313, '<td valign="top">Definitely bizarre. Comes across to me a bit dark. Perhaps some minor levels or curves adjustments to brighten it up a tad?</td>', 'Definitely bizarre. Comes across to me a bit dark. Perhaps some minor levels or curves adjustments to brighten it up a tad?', '2010-03-18 20:08:12.000000', NULL, 1),
(5909969, 861284, 83313, '<td valign="top">Great perspective on this, but I think I would have liked this quite a bit better without the heavy tonemapping.</td>', 'Great perspective on this, but I think I would have liked this quite a bit better without the heavy tonemapping.', '2010-03-18 20:11:34.000000', NULL, 1),
(5909970, 861339, 83313, '<td valign="top">Is Zagar a close relative of Oscar the Grouch?</td>', 'Is Zagar a close relative of Oscar the Grouch?', '2010-03-18 20:12:37.000000', NULL, 1),
(5909972, 861218, 83313, '<td valign="top">Electromagenetic Pulse?</td>', 'Electromagenetic Pulse?', '2010-03-18 20:13:18.000000', NULL, 1),
(5909974, 861238, 83313, '<td valign="top">I can imagine all the employees here arguing over who gets the good cubicle. The new guy always gets the small one with the weird shape.</td>', 'I can imagine all the employees here arguing over who gets the good cubicle. The new guy always gets the small one with the weird shape.', '2010-03-18 20:14:36.000000', NULL, 1),
