(5912978, 860453, 63633, '<td valign="top">This is my pick for the blue. So striking, and works so well in black and white. Great tonal range. Bumping.</td>', 'This is my pick for the blue. So striking, and works so well in black and white. Great tonal range. Bumping.', '2010-03-22 08:53:27.000000', NULL, 1),
(5913284, 860979, 113801, '<td valign="top">LOL! Awesome!</td>', 'LOL! Awesome!', '2010-03-22 12:50:05.000000', NULL, 1),
(5913463, 860490, 108580, '<td valign="top">:)<br/>Tongue in cheek title. Grey dilapidated walls contrasted by their colourful clothes gives me a sense of pride despite hardship and being ostracised.<br/>Did they build this themselves as a monument to the past?</td>', ':)Tongue in cheek title. Grey dilapidated walls contrasted by their colourful clothes gives me a sense of pride despite hardship and being ostracised.Did they build this themselves as a monument to the past?', '2010-03-22 15:08:33.000000', NULL, 1),
(5913500, 860699, 114472, '<td valign="top">Really nice! 8 from me</td>', 'Really nice! 8 from me', '2010-03-22 15:53:46.000000', NULL, 1),
(5913501, 861102, 27608, '<td valign="top">Awesome!  Although looks like you got a bit of flare top centre there.<br/> <br/>I love where you setup, as it can be pretty busy there in terms of cars, wires and junk.  Nice job.  I think this is you Jonathan!  Good luck!</td>', 'Awesome!  Although looks like you got a bit of flare top centre there. I love where you setup, as it can be pretty busy there in terms of cars, wires and junk.  Nice job.  I think this is you Jonathan!  Good luck!', '2010-03-22 15:56:07.000000', NULL, 1),
(5913505, 860979, 114472, '<td valign="top">Nice composition!</td>', 'Nice composition!', '2010-03-22 15:59:29.000000', NULL, 1),
(5913542, 860453, 5364, '<td valign="top">I think this is a great choice to go for an abstract of the building rather than the whole thing</td>', 'I think this is a great choice to go for an abstract of the building rather than the whole thing', '2010-03-22 16:33:57.000000', NULL, 1),
(5913543, 860235, 5364, '<td valign="top">While I like the simplicity, for me there''s a little too much negative space</td>', 'While I like the simplicity, for me there''s a little too much negative space', '2010-03-22 16:34:48.000000', NULL, 1),
(5913547, 861325, 5364, '<td valign="top">I like the angle you''ve got, but the wide border at the bottom makes it look like you''ve chopped off the feet of the building and spoils the composition</td>', 'I like the angle you''ve got, but the wide border at the bottom makes it look like you''ve chopped off the feet of the building and spoils the composition', '2010-03-22 16:36:53.000000', NULL, 1),
