(5915387, 861126, 99263, '<td valign="top">Congratulations on a great finish.</td>', 'Congratulations on a great finish.', '2010-03-24 03:08:08.000000', NULL, 0),
(5915388, 861327, 99263, '<td valign="top">Congratulations on a great finish.</td>', 'Congratulations on a great finish.', '2010-03-24 03:08:33.000000', NULL, 0),
(5915389, 860142, 99263, '<td valign="top">Congratulations on a great finish.</td>', 'Congratulations on a great finish.', '2010-03-24 03:08:55.000000', NULL, 0),
(5915390, 860979, 99263, '<td valign="top">Congratulations on a great finish.</td>', 'Congratulations on a great finish.', '2010-03-24 03:09:13.000000', NULL, 0),
