(5915394, 861089, 99263, '<td valign="top">Not the finish I predicted but maybe it wasn''t bizarre enough for most. I still find it a beautiful night shot. Would have done lots better probably if you had entered it in the night shot challenge.<br/> <br/>Edited: Spelling error.<br/><br/><i>Message edited by author 2010-03-24 03:30:47.</i></td>', 'Not the finish I predicted but maybe it wasn''t bizarre enough for most. I still find it a beautiful night shot. Would have done lots better probably if you had entered it in the night shot challenge. Edited: Spelling error.', '2010-03-24 03:13:11.000000', '2010-03-24 03:30:47.000000', 0),
(5915395, 860482, 99263, '<td valign="top">I still love this shot. One of my favorites.</td>', 'I still love this shot. One of my favorites.', '2010-03-24 03:14:36.000000', NULL, 0),
(5915396, 860486, 99263, '<td valign="top">Not the finish I had predicted but that''s probably due to it not being bizarre enough. Still an excellent image and one of my favorites.</td>', 'Not the finish I had predicted but that''s probably due to it not being bizarre enough. Still an excellent image and one of my favorites.', '2010-03-24 03:16:20.000000', NULL, 0),
(5915398, 860699, 99263, '<td valign="top">Not the finish I predicted but this remains one of my favorites.</td>', 'Not the finish I predicted but this remains one of my favorites.', '2010-03-24 03:17:07.000000', NULL, 0),
