(5915965, 861155, 102278, '<td valign="top">@ <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=64844" rel="nofollow" target="_blank">tamatama</a> - It''s actually Cardiff library. I could have got a better angle on the building but if i moved even slightly to the left or right i would have revealed the large sign saying so behind the vertical spike.</td>', '@  tamatama - It''s actually Cardiff library. I could have got a better angle on the building but if i moved even slightly to the left or right i would have revealed the large sign saying so behind the vertical spike.', '2010-03-24 12:52:02.000000', NULL, 0),
(5916074, 860453, 86218, '<td valign="top">Just an amazing shot and well processed and seen. It seems to play mind games when you look at it. Flat and then it has scenes that just jumps up at you. Dont know if this makes sense. (well if it doesnt I blame my insanity on DPc)Deserving Blue no doubt</td>', 'Just an amazing shot and well processed and seen. It seems to play mind games when you look at it. Flat and then it has scenes that just jumps up at you. Dont know if this makes sense. (well if it doesnt I blame my insanity on DPc)Deserving Blue no doubt', '2010-03-24 14:06:30.000000', NULL, 0),
